import React from "react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogActions,
  TextField,
  Button,
  Box,
  Container,
} from "@mui/material";

function AddTaskDialog({
  open,
  onClose,
  text,
  setText,
  description,
  setDescription,
  priority,
  setPriority,
  onAdd,
}) {
  return (
    <Container sx={{ bgcolor: blue }}>
      <Dialog open={open} onClose={onClose} fullWidth>
        <DialogTitle sx={{ bgcolor: "" }}>Descreva sua tarefa</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="Título da Tarefa"
            value={text}
            onChange={(e) => setText(e.target.value)}
            sx={{ mt: 2 }}
          />

          <TextField
            fullWidth
            multiline
            rows={3}
            label="Descrição"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            sx={{ mt: 2 }}
          />

          <TextField
            select
            fullWidth
            label="Prioridade"
            value={priority}
            onChange={(e) => setPriority(e.target.value)}
            SelectProps={{ native: true }}
            sx={{ mt: 2 }}
          >
            <option value="Normal">Normal</option>
            <option value="Urgente">Urgente</option>
            <option value="Imediato">Imediato</option>
          </TextField>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={onClose}
            variant="contained"
            sx={{
              bgcolor: "red",
              color: "#f1f1f1",
            }}
          >
            Cancelar
          </Button>
          <Button
            onClick={() => {
              onAdd();
              onClose();
            }}
            variant="contained"
          >
            Adicionar
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
}

export default AddTaskDialog;
